PRODUCTION_SOURCE = '"""\nOLA-045\nOracle Scheduler Cycle Lineage Completion Bridge\n\nCanonical typed bridge between the OLA-030 scheduler cycle boundary and\nOLA-044 persisted cohort lineage production wiring.\n\nPurpose:\n- invoke the existing OLA-017 cycle runner exactly once\n- preserve the exact OLA-017 cycle result object\n- require completed-cycle persistence evidence before lineage wiring\n- derive acquisition_batch_id from the pending OLA-042 stage metadata\n- require exactly one pending staged cohort for the completed cycle boundary\n- invoke OLA-044 with the exact cycle_completed_at timestamp\n- return the original OLA-017 result unchanged for existing OLA-030\n  scheduler result projection\n- retain the OLA-044 wiring receipt for audit and tests\n\nThis bridge does not alter OLA-021 scheduler kwargs.\nIt does not alter OLA-030 scheduler result projection.\nIt performs no acquisition or persistence itself.\n\nNo intelligence interpretation.\nNo signal scoring.\nNo alerts.\nNo Q Series handoff.\nNo execution.\n\nOracle remains permanently read-only.\n"""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom datetime import datetime, timezone\nfrom typing import Any, Callable, Mapping\n\nfrom .oracle_persisted_cohort_lineage_production_wiring_contract import (\n    OraclePersistedCohortLineageProductionWiringContract,\n    PersistedCohortLineageProductionWiringContractError,\n    PersistedCohortLineageProductionWiringInvariantError,\n    PersistedCohortLineageProductionWiringReceipt,\n)\n\n\nSCHEMA_VERSION = "OLA-045"\nENGINE_ID = "OLA-045"\n\nREAD_ONLY = True\nEXECUTION_ALLOWED = False\nEXECUTION_ADAPTER_RESOLVED = False\nEXECUTION_ADAPTER_INVOKED = False\nTRADE_AUTHORIZATION_ALLOWED = False\nORDER_PLACEMENT_ALLOWED = False\nFUNDS_MOVED = False\nPORTFOLIO_MUTATED = False\n\n\nclass SchedulerCycleLineageCompletionBridgeContractError(ValueError):\n    """Raised when OLA-045 bridge input is malformed."""\n\n\nclass SchedulerCycleLineageCompletionBridgeInvariantError(RuntimeError):\n    """Raised when permanent OLA-045 invariants are violated."""\n\n\ndef _require_utc_datetime(\n    value: Any,\n    field_name: str,\n) -> datetime:\n    if not isinstance(value, datetime):\n        raise SchedulerCycleLineageCompletionBridgeContractError(\n            f"{field_name} must be a datetime"\n        )\n\n    if value.tzinfo is None or value.utcoffset() is None:\n        raise SchedulerCycleLineageCompletionBridgeContractError(\n            f"{field_name} must be timezone-aware"\n        )\n\n    return value.astimezone(timezone.utc)\n\n\ndef _cycle_payload(\n    cycle_result: Any,\n) -> dict[str, Any]:\n    if hasattr(\n        cycle_result,\n        "to_canonical_dict",\n    ):\n        payload = cycle_result.to_canonical_dict()\n    elif isinstance(cycle_result, Mapping):\n        payload = cycle_result\n    else:\n        raise SchedulerCycleLineageCompletionBridgeContractError(\n            "OLA-017 cycle result must expose canonical mapping evidence"\n        )\n\n    if not isinstance(payload, Mapping):\n        raise SchedulerCycleLineageCompletionBridgeContractError(\n            "OLA-017 canonical cycle evidence must be a mapping"\n        )\n\n    return dict(payload)\n\n\n@dataclass(frozen=True, slots=True)\nclass SchedulerCycleLineageCompletionBridgeReceipt:\n    schema_version: str\n    engine_id: str\n    cycle_invocation_count: int\n    cycle_result_preserved: bool\n    lineage_completion_invoked: bool\n    acquisition_batch_id: str | None\n    lineage_wiring_receipt: (\n        PersistedCohortLineageProductionWiringReceipt | None\n    )\n    read_only: bool\n    execution_allowed: bool\n    execution_adapter_resolved: bool\n    execution_adapter_invoked: bool\n    trade_authorization_allowed: bool\n    order_placement_allowed: bool\n    funds_moved: bool\n    portfolio_mutated: bool\n\n    def assert_invariants(self) -> None:\n        if self.schema_version != SCHEMA_VERSION:\n            raise SchedulerCycleLineageCompletionBridgeInvariantError(\n                "schema version invariant violated"\n            )\n\n        if self.engine_id != ENGINE_ID:\n            raise SchedulerCycleLineageCompletionBridgeInvariantError(\n                "engine identity invariant violated"\n            )\n\n        if self.cycle_invocation_count != 1:\n            raise SchedulerCycleLineageCompletionBridgeInvariantError(\n                "OLA-017 cycle must be invoked exactly once"\n            )\n\n        if self.cycle_result_preserved is not True:\n            raise SchedulerCycleLineageCompletionBridgeInvariantError(\n                "OLA-017 cycle result preservation invariant violated"\n            )\n\n        if self.lineage_completion_invoked:\n            if self.acquisition_batch_id is None:\n                raise SchedulerCycleLineageCompletionBridgeInvariantError(\n                    "lineage completion requires acquisition batch identity"\n                )\n\n            if self.lineage_wiring_receipt is None:\n                raise SchedulerCycleLineageCompletionBridgeInvariantError(\n                    "lineage completion requires OLA-044 receipt"\n                )\n        else:\n            if self.lineage_wiring_receipt is not None:\n                raise SchedulerCycleLineageCompletionBridgeInvariantError(\n                    "non-completed cycle cannot carry lineage wiring receipt"\n                )\n\n        authority = (\n            self.read_only,\n            self.execution_allowed,\n            self.execution_adapter_resolved,\n            self.execution_adapter_invoked,\n            self.trade_authorization_allowed,\n            self.order_placement_allowed,\n            self.funds_moved,\n            self.portfolio_mutated,\n        )\n\n        if authority != (\n            True,\n            False,\n            False,\n            False,\n            False,\n            False,\n            False,\n            False,\n        ):\n            raise SchedulerCycleLineageCompletionBridgeInvariantError(\n                "OLA-045 read-only authority invariants violated"\n            )\n\n\nclass OracleSchedulerCycleLineageCompletionBridge:\n    read_only = True\n    execution_allowed = False\n\n    def __init__(\n        self,\n        *,\n        production_wiring: (\n            OraclePersistedCohortLineageProductionWiringContract\n        ),\n    ) -> None:\n        if not isinstance(\n            production_wiring,\n            OraclePersistedCohortLineageProductionWiringContract,\n        ):\n            raise SchedulerCycleLineageCompletionBridgeContractError(\n                "production_wiring must be an OLA-044 production wiring contract"\n            )\n\n        self._production_wiring = production_wiring\n        self._last_receipt: (\n            SchedulerCycleLineageCompletionBridgeReceipt | None\n        ) = None\n\n    @property\n    def production_wiring(\n        self,\n    ) -> OraclePersistedCohortLineageProductionWiringContract:\n        return self._production_wiring\n\n    @property\n    def last_receipt(\n        self,\n    ) -> SchedulerCycleLineageCompletionBridgeReceipt | None:\n        return self._last_receipt\n\n    def run_cycle(\n        self,\n        *,\n        cycle_runner: Callable[..., Any],\n        cycle_completed_at: datetime,\n        cycle_kwargs: Mapping[str, Any],\n    ) -> Any:\n        if not callable(cycle_runner):\n            raise SchedulerCycleLineageCompletionBridgeContractError(\n                "cycle_runner must be callable"\n            )\n\n        if not isinstance(cycle_kwargs, Mapping):\n            raise SchedulerCycleLineageCompletionBridgeContractError(\n                "cycle_kwargs must be a mapping"\n            )\n\n        completed_at = _require_utc_datetime(\n            cycle_completed_at,\n            "cycle_completed_at",\n        )\n\n        cycle_result = cycle_runner(\n            **dict(cycle_kwargs)\n        )\n\n        cycle_payload_before = _cycle_payload(\n            cycle_result\n        )\n\n        if (\n            cycle_payload_before.get("schema_version")\n            != "OLA-017"\n            or cycle_payload_before.get("engine_id")\n            != "OLA-017"\n        ):\n            raise SchedulerCycleLineageCompletionBridgeContractError(\n                "cycle result must preserve OLA-017 identity"\n            )\n\n        cycle_status = cycle_payload_before.get(\n            "cycle_status",\n            cycle_payload_before.get("status"),\n        )\n\n        lineage_completion_invoked = False\n        acquisition_batch_id: str | None = None\n        lineage_wiring_receipt = None\n\n        if cycle_status == "completed":\n            (\n                acquisition_batch_id\n            ) = self._resolve_single_pending_batch_id()\n\n            try:\n                (\n                    preserved_result,\n                    lineage_wiring_receipt,\n                ) = self._production_wiring.complete_persisted_cycle(\n                    ola_017_cycle_result=cycle_result,\n                    acquisition_batch_id=acquisition_batch_id,\n                    cycle_completed_at=completed_at,\n                )\n            except PersistedCohortLineageProductionWiringContractError as exc:\n                raise SchedulerCycleLineageCompletionBridgeContractError(\n                    f"OLA-044 production wiring rejected completed cycle: {exc}"\n                ) from exc\n            except PersistedCohortLineageProductionWiringInvariantError as exc:\n                raise SchedulerCycleLineageCompletionBridgeInvariantError(\n                    f"OLA-044 production wiring invariant failed: {exc}"\n                ) from exc\n\n            if preserved_result is not cycle_result:\n                raise SchedulerCycleLineageCompletionBridgeInvariantError(\n                    "OLA-044 did not preserve exact OLA-017 result object"\n                )\n\n            lineage_completion_invoked = True\n\n        cycle_payload_after = _cycle_payload(\n            cycle_result\n        )\n\n        if cycle_payload_after != cycle_payload_before:\n            raise SchedulerCycleLineageCompletionBridgeInvariantError(\n                "OLA-017 cycle result mutated across lineage completion bridge"\n            )\n\n        receipt = SchedulerCycleLineageCompletionBridgeReceipt(\n            schema_version=SCHEMA_VERSION,\n            engine_id=ENGINE_ID,\n            cycle_invocation_count=1,\n            cycle_result_preserved=True,\n            lineage_completion_invoked=lineage_completion_invoked,\n            acquisition_batch_id=acquisition_batch_id,\n            lineage_wiring_receipt=lineage_wiring_receipt,\n            read_only=READ_ONLY,\n            execution_allowed=EXECUTION_ALLOWED,\n            execution_adapter_resolved=EXECUTION_ADAPTER_RESOLVED,\n            execution_adapter_invoked=EXECUTION_ADAPTER_INVOKED,\n            trade_authorization_allowed=TRADE_AUTHORIZATION_ALLOWED,\n            order_placement_allowed=ORDER_PLACEMENT_ALLOWED,\n            funds_moved=FUNDS_MOVED,\n            portfolio_mutated=PORTFOLIO_MUTATED,\n        )\n\n        receipt.assert_invariants()\n        self._last_receipt = receipt\n\n        return cycle_result\n\n    def _resolve_single_pending_batch_id(\n        self,\n    ) -> str:\n        staging_router = (\n            self._production_wiring.staged_persistence_router\n        )\n\n        pending = getattr(\n            staging_router,\n            "_pending",\n            None,\n        )\n\n        if not isinstance(pending, dict):\n            raise SchedulerCycleLineageCompletionBridgeInvariantError(\n                "OLA-042 pending stage registry is unavailable"\n            )\n\n        pending_batch_ids = tuple(\n            pending.keys()\n        )\n\n        if len(pending_batch_ids) != 1:\n            raise SchedulerCycleLineageCompletionBridgeContractError(\n                "completed OLA-017 cycle requires exactly one pending OLA-042 staged cohort"\n            )\n\n        batch_id = pending_batch_ids[0]\n\n        if not isinstance(batch_id, str) or not batch_id.strip():\n            raise SchedulerCycleLineageCompletionBridgeInvariantError(\n                "OLA-042 pending acquisition batch identity is malformed"\n            )\n\n        return batch_id.strip()\n'

TEST_SOURCE = 'from datetime import datetime, timezone\n\nfrom qseries_v2.oracle_intelligence.live_acquisition.oracle_scheduler_cycle_lineage_completion_bridge import (\n    OracleSchedulerCycleLineageCompletionBridge,\n    SchedulerCycleLineageCompletionBridgeContractError,\n)\nfrom qseries_v2.oracle_intelligence.live_acquisition.oracle_persisted_cohort_lineage_production_wiring_contract import (\n    OraclePersistedCohortLineageProductionWiringContract,\n)\nfrom qseries_v2.oracle_intelligence.live_acquisition.oracle_live_read_only_acquisition_runtime import (\n    CanonicalObservation,\n    ObservationRoutingEvidence,\n    RawSourceObservation,\n)\n\n\nT1 = datetime(\n    2026,\n    7,\n    14,\n    19,\n    0,\n    0,\n    tzinfo=timezone.utc,\n)\nT2 = datetime(\n    2026,\n    7,\n    14,\n    19,\n    0,\n    15,\n    tzinfo=timezone.utc,\n)\nT3 = datetime(\n    2026,\n    7,\n    14,\n    19,\n    0,\n    30,\n    tzinfo=timezone.utc,\n)\n\n\ndef build_observation(\n    *,\n    market_id,\n    frame_id,\n    batch_id,\n    yes_ask="0.6140",\n):\n    payload = {\n        "source_market_id": market_id,\n        "yes_bid_dollars": "0.0000",\n        "yes_bid_size_fp": "0.00",\n        "yes_ask_dollars": yes_ask,\n        "yes_ask_size_fp": "40.00",\n        "no_bid_dollars": "0.3860",\n        "no_ask_dollars": "0.0000",\n        "last_price_dollars": "0.0000",\n        "previous_yes_bid_dollars": "0.0000",\n        "previous_yes_ask_dollars": "0.6000",\n        "previous_price_dollars": "0.0000",\n        "volume_fp": "0.00",\n        "volume_24h_fp": "0.00",\n        "open_interest_fp": "0.00",\n        "liquidity_dollars": "0.0000",\n    }\n\n    raw = RawSourceObservation.create(\n        source_observation_id=(\n            "kalshi."\n            + market_id\n            + "."\n            + frame_id\n        ),\n        observed_at=T1,\n        observation_type="market_snapshot",\n        payload=payload,\n        provenance={\n            "source_id": "source.kalshi.market_data",\n            "frame_id": frame_id,\n        },\n    )\n\n    return CanonicalObservation.create(\n        source_id="source.kalshi.market_data",\n        raw_observation=raw,\n        acquired_at=T1,\n        acquisition_batch_id=batch_id,\n    )\n\n\ndef build_cohort(\n    *,\n    cycle_number,\n    changed_market=None,\n):\n    batch_id = f"batch.ola.045.{cycle_number}"\n\n    return tuple(\n        build_observation(\n            market_id=f"KXTEST-SCHED-LINEAGE-{index}",\n            frame_id=f"{cycle_number}-{index}",\n            batch_id=batch_id,\n            yes_ask=(\n                "0.9700"\n                if changed_market\n                == f"KXTEST-SCHED-LINEAGE-{index}"\n                else "0.6140"\n            ),\n        )\n        for index in range(1, 6)\n    )\n\n\nclass FakeProductionPersistenceRouter:\n    def route_batch(\n        self,\n        observations,\n        routed_at,\n    ):\n        return tuple(\n            ObservationRoutingEvidence.create(\n                observation_id=observation.observation_id,\n                routed_at=routed_at,\n                accepted=True,\n                route_id="fake.ola.045.persistence",\n                metadata={\n                    "test": "OLA-045",\n                },\n            )\n            for observation in observations\n        )\n\n    def __call__(\n        self,\n        observation,\n        routed_at,\n    ):\n        return ObservationRoutingEvidence.create(\n            observation_id=observation.observation_id,\n            routed_at=routed_at,\n            accepted=True,\n            route_id="fake.ola.045.persistence.single",\n            metadata={\n                "test": "OLA-045",\n            },\n        )\n\n\nclass FakeCycleRunner:\n    def __init__(\n        self,\n        result,\n    ):\n        self.result = result\n        self.call_count = 0\n        self.last_kwargs = None\n\n    def __call__(\n        self,\n        **kwargs,\n    ):\n        self.call_count += 1\n        self.last_kwargs = dict(kwargs)\n        return self.result\n\n\ndef completed_cycle_result():\n    return {\n        "schema_version": "OLA-017",\n        "engine_id": "OLA-017",\n        "cycle_status": "completed",\n        "canonical_count": 5,\n        "postgresql_routing_record_delta": 5,\n        "read_only": True,\n        "execution_allowed": False,\n    }\n\n\ndef build_bridge():\n    production_wiring = (\n        OraclePersistedCohortLineageProductionWiringContract(\n            production_persistence_router=(\n                FakeProductionPersistenceRouter()\n            )\n        )\n    )\n\n    bridge = OracleSchedulerCycleLineageCompletionBridge(\n        production_wiring=production_wiring\n    )\n\n    return bridge, production_wiring\n\n\ndef stage_cycle(\n    production_wiring,\n    *,\n    cycle_number,\n    routed_at,\n    changed_market=None,\n):\n    cohort = build_cohort(\n        cycle_number=cycle_number,\n        changed_market=changed_market,\n    )\n\n    production_wiring.staged_persistence_router.route_batch(\n        cohort,\n        routed_at,\n    )\n\n    return cohort\n\n\ndef run_completed_cycle_test():\n    bridge, wiring = build_bridge()\n\n    stage_cycle(\n        wiring,\n        cycle_number=1,\n        routed_at=T1,\n    )\n\n    result = completed_cycle_result()\n    result_before = dict(result)\n    runner = FakeCycleRunner(result)\n\n    returned = bridge.run_cycle(\n        cycle_runner=runner,\n        cycle_completed_at=T1,\n        cycle_kwargs={\n            "alpha": "beta",\n            "count": 5,\n        },\n    )\n\n    assert returned is result\n    assert result == result_before\n    assert runner.call_count == 1\n    assert runner.last_kwargs == {\n        "alpha": "beta",\n        "count": 5,\n    }\n\n    receipt = bridge.last_receipt\n\n    assert receipt is not None\n    assert receipt.schema_version == "OLA-045"\n    assert receipt.engine_id == "OLA-045"\n    assert receipt.cycle_invocation_count == 1\n    assert receipt.cycle_result_preserved is True\n    assert receipt.lineage_completion_invoked is True\n    assert receipt.acquisition_batch_id == "batch.ola.045.1"\n    assert receipt.lineage_wiring_receipt is not None\n    assert (\n        receipt\n        .lineage_wiring_receipt\n        .lineage_record_count_after\n        == 5\n    )\n\n    return bridge, wiring, receipt\n\n\ndef run_repeated_cycle_test():\n    bridge, wiring, _ = run_completed_cycle_test()\n\n    stage_cycle(\n        wiring,\n        cycle_number=2,\n        routed_at=T2,\n    )\n\n    runner = FakeCycleRunner(\n        completed_cycle_result()\n    )\n\n    bridge.run_cycle(\n        cycle_runner=runner,\n        cycle_completed_at=T2,\n        cycle_kwargs={\n            "cycle": 2,\n        },\n    )\n\n    receipt = bridge.last_receipt\n\n    assert receipt is not None\n    assert receipt.lineage_completion_invoked is True\n    assert (\n        receipt\n        .lineage_wiring_receipt\n        .lineage_record_count_after\n        == 10\n    )\n    assert (\n        receipt\n        .lineage_wiring_receipt\n        .transition_count\n        == 0\n    )\n\n    return bridge, wiring, receipt\n\n\ndef run_changed_cycle_test():\n    bridge, wiring, _ = run_repeated_cycle_test()\n\n    stage_cycle(\n        wiring,\n        cycle_number=3,\n        routed_at=T3,\n        changed_market="KXTEST-SCHED-LINEAGE-3",\n    )\n\n    runner = FakeCycleRunner(\n        completed_cycle_result()\n    )\n\n    bridge.run_cycle(\n        cycle_runner=runner,\n        cycle_completed_at=T3,\n        cycle_kwargs={\n            "cycle": 3,\n        },\n    )\n\n    receipt = bridge.last_receipt\n\n    assert receipt is not None\n    assert receipt.lineage_wiring_receipt is not None\n    assert (\n        receipt\n        .lineage_wiring_receipt\n        .transition_count\n        == 1\n    )\n    assert (\n        receipt\n        .lineage_wiring_receipt\n        .lineage_record_count_after\n        == 15\n    )\n\n    ledger = (\n        wiring\n        .lineage_bridge\n        .coordinator\n        .lineage_cycle_bridge\n        .batch_router\n        .bridge\n        .ledger\n    )\n\n    changed = ledger.head(\n        source_id="source.kalshi.market_data",\n        source_market_id="KXTEST-SCHED-LINEAGE-3",\n    )\n\n    unchanged = ledger.head(\n        source_id="source.kalshi.market_data",\n        source_market_id="KXTEST-SCHED-LINEAGE-1",\n    )\n\n    assert changed is not None\n    assert unchanged is not None\n    assert changed.transition_detected is True\n    assert changed.state_changed_at == T3\n    assert changed.consecutive_frame_count == 1\n    assert changed.dwell_seconds == "0.000000"\n    assert unchanged.consecutive_frame_count == 3\n    assert unchanged.dwell_seconds == "30.000000"\n\n    return receipt\n\n\ndef run_failed_cycle_does_not_promote_test():\n    bridge, wiring = build_bridge()\n\n    stage_cycle(\n        wiring,\n        cycle_number=1,\n        routed_at=T1,\n    )\n\n    failed = {\n        "schema_version": "OLA-017",\n        "engine_id": "OLA-017",\n        "cycle_status": "failed",\n        "canonical_count": 0,\n        "postgresql_routing_record_delta": 0,\n        "read_only": True,\n        "execution_allowed": False,\n    }\n\n    runner = FakeCycleRunner(failed)\n\n    returned = bridge.run_cycle(\n        cycle_runner=runner,\n        cycle_completed_at=T1,\n        cycle_kwargs={},\n    )\n\n    assert returned is failed\n    assert runner.call_count == 1\n\n    receipt = bridge.last_receipt\n\n    assert receipt is not None\n    assert receipt.lineage_completion_invoked is False\n    assert receipt.acquisition_batch_id is None\n    assert receipt.lineage_wiring_receipt is None\n    assert (\n        wiring\n        .staged_persistence_router\n        .pending_stage_count\n        == 1\n    )\n\n\ndef run_missing_stage_fails_closed_test():\n    bridge, _ = build_bridge()\n    runner = FakeCycleRunner(\n        completed_cycle_result()\n    )\n\n    try:\n        bridge.run_cycle(\n            cycle_runner=runner,\n            cycle_completed_at=T1,\n            cycle_kwargs={},\n        )\n        raise AssertionError(\n            "completed cycle without staged cohort must fail closed"\n        )\n    except SchedulerCycleLineageCompletionBridgeContractError:\n        pass\n\n    assert runner.call_count == 1\n\n\ndef run_multiple_pending_stages_fail_closed_test():\n    bridge, wiring = build_bridge()\n\n    stage_cycle(\n        wiring,\n        cycle_number=1,\n        routed_at=T1,\n    )\n    stage_cycle(\n        wiring,\n        cycle_number=2,\n        routed_at=T2,\n    )\n\n    runner = FakeCycleRunner(\n        completed_cycle_result()\n    )\n\n    try:\n        bridge.run_cycle(\n            cycle_runner=runner,\n            cycle_completed_at=T2,\n            cycle_kwargs={},\n        )\n        raise AssertionError(\n            "ambiguous staged cohort boundary must fail closed"\n        )\n    except SchedulerCycleLineageCompletionBridgeContractError:\n        pass\n\n    assert runner.call_count == 1\n    assert (\n        wiring\n        .staged_persistence_router\n        .pending_stage_count\n        == 2\n    )\n\n\ndef run_exact_cycle_kwargs_forwarding_test():\n    bridge, wiring = build_bridge()\n\n    stage_cycle(\n        wiring,\n        cycle_number=1,\n        routed_at=T1,\n    )\n\n    runner = FakeCycleRunner(\n        completed_cycle_result()\n    )\n\n    kwargs = {\n        "source_control_decision": "typed-record-placeholder",\n        "cycle_started_at": T1,\n        "cycle_completed_at": T1,\n        "replay_metadata": {\n            "launch": "OLA-030",\n        },\n        "audit_metadata": {\n            "launch": "OLA-030",\n        },\n    }\n\n    bridge.run_cycle(\n        cycle_runner=runner,\n        cycle_completed_at=T1,\n        cycle_kwargs=kwargs,\n    )\n\n    assert runner.last_kwargs == kwargs\n\n\ndef run_deterministic_bridge_replay_test():\n    def execute():\n        bridge, wiring = build_bridge()\n        receipts = []\n\n        for cycle_number, observed_at, changed_market in (\n            (1, T1, None),\n            (2, T2, None),\n            (\n                3,\n                T3,\n                "KXTEST-SCHED-LINEAGE-5",\n            ),\n        ):\n            stage_cycle(\n                wiring,\n                cycle_number=cycle_number,\n                routed_at=observed_at,\n                changed_market=changed_market,\n            )\n\n            bridge.run_cycle(\n                cycle_runner=FakeCycleRunner(\n                    completed_cycle_result()\n                ),\n                cycle_completed_at=observed_at,\n                cycle_kwargs={\n                    "cycle": cycle_number,\n                },\n            )\n\n            receipts.append(\n                bridge.last_receipt\n            )\n\n        records = (\n            wiring\n            .lineage_bridge\n            .coordinator\n            .lineage_cycle_bridge\n            .batch_router\n            .bridge\n            .ledger\n            .records()\n        )\n\n        return tuple(receipts), records\n\n    first_receipts, first_records = execute()\n    second_receipts, second_records = execute()\n\n    assert first_receipts == second_receipts\n    assert first_records == second_records\n\n    return first_receipts, first_records\n\n\ndef main():\n    _, _, first = run_completed_cycle_test()\n    _, _, second = run_repeated_cycle_test()\n    third = run_changed_cycle_test()\n\n    run_failed_cycle_does_not_promote_test()\n    run_missing_stage_fails_closed_test()\n    run_multiple_pending_stages_fail_closed_test()\n    run_exact_cycle_kwargs_forwarding_test()\n\n    replay_receipts, replay_records = (\n        run_deterministic_bridge_replay_test()\n    )\n\n    result = {\n        "schema_version": third.schema_version,\n        "engine_id": third.engine_id,\n        "status": "passed",\n        "ola_017_cycle_invoked_exactly_once": True,\n        "exact_cycle_kwargs_forwarded": True,\n        "exact_ola_017_result_object_preserved": True,\n        "ola_017_result_mapping_preserved": True,\n        "completed_cycle_requires_single_pending_stage": True,\n        "ola_044_production_wiring_invoked_after_completed_cycle": True,\n        "cycle_completed_at_bound_to_lineage": True,\n        "first_cycle_advanced_five_lineage_records": (\n            first\n            .lineage_wiring_receipt\n            .lineage_record_count_after\n            == 5\n        ),\n        "second_cycle_advanced_dwell": (\n            second\n            .lineage_wiring_receipt\n            .lineage_record_count_after\n            == 10\n        ),\n        "third_cycle_detected_exact_state_change": (\n            third\n            .lineage_wiring_receipt\n            .transition_count\n            == 1\n        ),\n        "failed_cycle_does_not_promote_stage": True,\n        "missing_stage_fails_closed": True,\n        "multiple_pending_stages_fail_closed": True,\n        "scheduler_kwargs_unchanged": True,\n        "scheduler_result_projection_not_owned": True,\n        "deterministic_scheduler_lineage_replay_valid": (\n            len(replay_receipts) == 3\n            and len(replay_records) == 15\n        ),\n        "no_acquisition_owned": True,\n        "no_persistence_owned": True,\n        "no_intelligence_interpretation": True,\n        "no_signal_scoring": True,\n        "alerts_allowed": False,\n        "qseries_handoff_allowed": False,\n        "read_only": third.read_only,\n        "execution_allowed": third.execution_allowed,\n        "execution_adapter_resolved": (\n            third.execution_adapter_resolved\n        ),\n        "execution_adapter_invoked": (\n            third.execution_adapter_invoked\n        ),\n        "trade_authorization_allowed": (\n            third.trade_authorization_allowed\n        ),\n        "order_placement_allowed": (\n            third.order_placement_allowed\n        ),\n        "funds_moved": third.funds_moved,\n        "portfolio_mutated": third.portfolio_mutated,\n    }\n\n    print(\n        "[PASS] OLA-045 Oracle Scheduler Cycle "\n        "Lineage Completion Bridge"\n    )\n    print(result)\n\n\nif __name__ == "__main__":\n    main()\n'


def write_full_replacement(path: Path, source: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(
        source,
        encoding="utf-8",
        newline="\n",
    )
    print(f"[OK] FULL REPLACEMENT: {path}")


